#!/bin/bash
# CarMax Extension installer — run with: bash <(pbpaste)
set -e
EXT="$HOME/carmax-ext"
echo "📦 Устанавливаю CarMax Extension..."
mkdir -p "$EXT"
echo '' | base64 -d | tar -xzf - -C "$EXT"
echo "✅ Файлы установлены в $EXT"
cp "$0" "$HOME/carmax-update.sh" 2>/dev/null && chmod +x "$HOME/carmax-update.sh" && echo "💾 Скрипт сохранён как ~/carmax-update.sh"
osascript << 'AS'
tell application "Google Chrome"
  activate
  open location "chrome://extensions/"
end tell
AS
echo "🎉 Готово!"
